// Publication dataset of the facts register v1.2 (D1); OC-02 follows v1.6, and the learner stories ST-01, ST-02 and ST-05 are anonymized outcome lines (no names in the public dataset, D13). Only V facts and R facts with a public scope (`allow`) are included; U facts and never-publish R facts stay in the private register. Wording, caveats, status and sources are canonical.
// Everything exported here can be rendered on a public page: no internal notes live in this file, and
// facts that must never be published (unverified or never-publish restricted items) stay in the private register.
// Citations (D16) are public or primary only; the status gate (D15) is enforced by scripts/check-facts.mjs.
export type CaveatClass = 'S' | 'R' | 'P' | 'I' | 'E' | 'X';
/** V verified · U unverified (blocked outside /news/) · R restricted (only on the paths in `allow`). */
export type FactStatus = 'V' | 'U' | 'R';
export interface Source { id: string; label: string; citation: string; url?: string }
export interface StatDisplay { value: string; numeric?: number; decimals?: number; prefix?: string; suffix?: string; from?: string; label: string }
export interface Fact {
  id: string;
  group: 'identity' | 'scale' | 'outcomes' | 'rct' | 'programs' | 'stories' | 'government' | 'partners' | 'design' | 'initiatives' | 'context';
  status: FactStatus;
  text: string;
  /** Alternative public headline wording (authoritative copy), where the register brief defines one. */
  headline?: string;
  stat?: StatDisplay;
  caveat?: CaveatClass;
  /** Wording shown in this fact's footnote instead of the class caveat text (a projection that needs its own words). Never de-duplicated against another fact's caveat. */
  caveatText?: string;
  /**
   * What a footnote on this fact annotates, as a phrase that stands alone in the Notes list. Defaults to the stat label, else the full
   * text; set it where the stat label names only one of several figures the fact carries (m3).
   */
  claim?: string;
  /** Sample base (n) shown in the footnote. */
  base?: string;
  /** Plain-language extra note readers may see in the footnote. */
  footnote?: string;
  sourceIds: string[];
  /** R facts only: path prefixes (site-relative, e.g. "/news/") where the fact may render. Empty/absent = nowhere. */
  allow?: string[];
}

